import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-siete-deficiencias-del-pueblo-de-dios', 'C',
 [dict(t=2231, e=2298, titulo='Ser sinceros', txt='Una de las cosas que nos sirve en nuestra vida cristiana es ser sinceros. Diga conmigo: yo voy a ser sincero. No decir mentiras, ser sincero. […] Que usted sea sincero con Dios. Realmente es bonito encontrar una persona que sea sincera, que no hay doblez, que no inventa, que no miente, que no agarra las cosas a su favor, sino que realmente dice: «Me equivoqué». Eso no es fácil. […] ¿Quién quiere dar su brazo a torcer? Eso cuesta. Pero cuando uno está de parte de Dios, el Señor le redarguye, porque una de las cosas que hace el Espíritu Santo […] te guía toda verdad, te revela todas las cosas y te redarguye de pecado.'),
  dict(t=3047, e=3110, titulo='Quítate todo orgullo', txt='En la primera no pasó nada. En la segunda no pasó nada, pero ya tenía más fe; si no, no se hubiera metido en la tercera, ni en la cuarta, ni en la quinta, ni en la sexta. Cuando iba en la sexta, dijo: «Solo una queda. Esta es mi oportunidad». Y se metió, hermano. […] Y eso es lo que Dios quiere: que te quites todo orgullo para que te metas, zambullido, siete veces en el Jordán y para que cuando salgas seas otra persona. Mire qué tremendo, porque Naamán era ateo, no era cristiano. Y cuando él salió y vio el poder de Dios, aceptó al Señor, hermano.'),
  dict(t=4247, e=4303, titulo='La Santa Cena, con todo el corazón', txt='Cuidado con tomar la Santa Cena mal, porque dice que te puede debilitar, te puede enfermar o te puede matar. Entonces, yo no sé cómo puede tomar la Santa Cena como si nada, nada pasó. Es despreciar la mesa del Señor. Por eso, cuando usted la tome, tómela con todo su corazón. Con todo su corazón. Si está en pecado, arrepiéntase y tómela ya arrepentido, para que […] sea digno, en el nombre de Jesús.')],
 [dict(t=2333, txt='Una de las cosas que más cuesta y que definitivamente va a llevar a un cristiano a no irse con el Señor, que no acepte su error y que no quiera cambiar.'),
  dict(t=2801, txt='Si no tuviéramos deficiencias, usted no estuviera aquí. Ya se hubiera ido al cielo como angelito.'),
  dict(t=4393, txt='La vida cristiana no puedes decir: «Yo la sigo si a mí me amoldan como yo quiero». Ese no es el cristianismo. La vida cristiana es: «Le voy a entrar, me cueste o no me cueste».')],
 ['¿En qué área de tu vida necesitas ser más sincero, con Dios, con tu familia y con tu iglesia, y decir sin excusas «me equivoqué»?',
  '¿Qué deficiencia, un carácter duro, el orgullo o una costumbre, sigues sin querer soltar? ¿Qué paso darías esta semana para avanzar y no quedarte estancado?',
  'Naamán tuvo que humillarse y obedecer aunque no entendía: ¿en qué debes «meterte al Jordán» hoy? Y la próxima vez que tomes la Santa Cena, ¿cómo la tomarás?'],
 inicio=691)
